actions.apply:
$r = Repair-WindowsImage -Online -ScanHealth -NoRestart -ErrorAction Stop
$s = [string]$r.ImageHealthState
if ($s -eq 'Repairable') { throw 'Der Komponentenspeicher hat Fehler. Starte jetzt: Windows-Abbild reparieren (DISM RestoreHealth).' }
if ($s -eq 'NonRepairable') { throw 'Der Komponentenspeicher ist nicht mehr reparierbar. Hier hilft nur eine Reparatur-Installation von Windows.' }

$exe = Join-Path $env:SystemRoot 'System32\ipconfig.exe'
$null = & $exe /flushdns 2>&1
if ($LASTEXITCODE -ne 0) { throw ('ipconfig /flushdns fehlgeschlagen (Code ' + $LASTEXITCODE + '). Laeuft der DNS-Client-Dienst?') }

$exe = Join-Path $env:SystemRoot 'System32\ipconfig.exe'
$null = & $exe /release 2>&1
$null = & $exe /renew 2>&1
$ok = $false
for ($i = 0; $i -lt 30 -and -not $ok; $i++) {
    $up = @(Get-NetIPConfiguration -ErrorAction SilentlyContinue | Where-Object { $null -ne $_.IPv4DefaultGateway -and $null -ne $_.NetAdapter -and [string]$_.NetAdapter.Status -eq 'Up' })
    if ($up.Count -gt 0) { $ok = $true } else { Start-Sleep -Seconds 1 }
}
if (-not $ok) { throw 'Nach dem Erneuern hat kein Netzwerkadapter eine Verbindung (kein Standardgateway). Kabel oder WLAN kontrollieren, notfalls den PC neu starten.' }

$sid = (Get-Process -Id $PID).SessionId
$targets = @((Join-Path $env:LOCALAPPDATA 'IconCache.db'), (Join-Path $env:LOCALAPPDATA 'Microsoft\Windows\Explorer\iconcache_*.db'))
$shell = @(Get-Process -Name explorer -ErrorAction SilentlyContinue | Where-Object { $_.SessionId -eq $sid })
$failed = 0
try {
    foreach ($p in $shell) { try { Stop-Process -Id $p.Id -Force -ErrorAction Stop } catch { $null = $_ } }
    foreach ($p in $shell) { try { $null = $p.WaitForExit(10000) } catch { $null = $_ } }
    foreach ($t in $targets) {
        foreach ($f in @(Get-ChildItem -Path $t -Force -ErrorAction SilentlyContinue)) {
            try { Remove-Item -LiteralPath $f.FullName -Force -ErrorAction Stop } catch { $failed++ }
        }
    }
} finally {
    $now = @()
    for ($i = 0; $i -lt 16 -and $now.Count -eq 0; $i++) {
        Start-Sleep -Milliseconds 500
        $now = @(Get-Process -Name explorer -ErrorAction SilentlyContinue | Where-Object { $_.SessionId -eq $sid })
    }
    if ($now.Count -eq 0 -and $shell.Count -gt 0) { Start-Process -FilePath (Join-Path $env:SystemRoot 'explorer.exe') }
}
if ($failed -gt 0) { throw ([string]$failed + ' Datei(en) waren gesperrt und konnten nicht entfernt werden. Nach einem Neustart einfach erneut starten.') }

$exe = Join-Path $env:SystemRoot 'System32\WSReset.exe'
if (-not (Test-Path -LiteralPath $exe)) { throw 'WSReset.exe wurde nicht gefunden.' }
$p = Start-Process -FilePath $exe -PassThru -WindowStyle Hidden -ErrorAction Stop
if (-not $p.WaitForExit(180000)) { throw 'WSReset hat nach 3 Minuten nicht geantwortet.' }

$root = $env:SystemRoot
$wasRunning = @()
foreach ($n in @('usosvc', 'wuauserv', 'bits', 'cryptsvc')) {
    $s = Get-Service -Name $n -ErrorAction SilentlyContinue
    if ($null -ne $s -and [string]$s.Status -ne 'Stopped') {
        $wasRunning += $n
        try { Stop-Service -Name $n -Force -ErrorAction Stop } catch { $null = $_ }
    }
}
$items = @(
    @{ Src = (Join-Path $root 'SoftwareDistribution'); New = 'SoftwareDistribution.velox-old' },
    @{ Src = (Join-Path $root 'System32\catroot2'); New = 'catroot2.velox-old' }
)
$err = $null
try {
    foreach ($it in $items) {
        $old = Join-Path (Split-Path -Parent $it.Src) $it.New
        if (Test-Path -LiteralPath $old) { Remove-Item -LiteralPath $old -Recurse -Force -ErrorAction SilentlyContinue }
        if (Test-Path -LiteralPath $it.Src) { Rename-Item -LiteralPath $it.Src -NewName $it.New -ErrorAction Stop }
    }
} catch {
    $err = $_.Exception.Message
} finally {
    foreach ($n in @('cryptsvc', 'bits', 'wuauserv', 'usosvc')) {
        if ($n -eq 'cryptsvc' -or $wasRunning -contains $n) { try { Start-Service -Name $n -ErrorAction Stop } catch { $null = $_ } }
    }
}
if ($null -ne $err) { throw ('Windows-Update-Reset fehlgeschlagen: ' + $err) }
foreach ($it in $items) {
    $old = Join-Path (Split-Path -Parent $it.Src) $it.New
    if (Test-Path -LiteralPath $old) { Remove-Item -LiteralPath $old -Recurse -Force -ErrorAction SilentlyContinue }
}

$svc = Get-CimInstance -ClassName Win32_Service -Filter "Name='WSearch'" -ErrorAction Stop
if ($null -eq $svc) { throw 'Windows Search ist auf diesem PC nicht vorhanden.' }
if ([string]$svc.StartMode -eq 'Disabled') { throw 'Der Dienst Windows Search ist deaktiviert. Schalte ihn zuerst wieder ein.' }
Stop-Service -Name WSearch -Force -ErrorAction Stop
$base = [Microsoft.Win32.RegistryKey]::OpenBaseKey([Microsoft.Win32.RegistryHive]::LocalMachine, [Microsoft.Win32.RegistryView]::Registry64)
$k = $base.OpenSubKey('SOFTWARE\Microsoft\Windows Search', $true)
if ($null -eq $k) { $base.Close(); throw 'Registry-Schluessel von Windows Search fehlt.' }
try { $k.SetValue('SetupCompletedSuccessfully', 0, [Microsoft.Win32.RegistryValueKind]::DWord) } finally { $k.Close(); $base.Close() }
Start-Service -Name WSearch -ErrorAction Stop

$s = Get-Service -Name W32Time -ErrorAction SilentlyContinue
if ($null -eq $s) { throw 'Der Windows-Zeitdienst (W32Time) fehlt.' }
if ([string]$s.Status -ne 'Running') { Start-Service -Name W32Time -ErrorAction Stop; Start-Sleep -Seconds 2 }
$exe = Join-Path $env:SystemRoot 'System32\w32tm.exe'
$null = & $exe /resync /force 2>&1
if ($LASTEXITCODE -ne 0) {
    $null = & $exe /config /update 2>&1
    Start-Sleep -Seconds 2
    $null = & $exe /resync /force 2>&1
    if ($LASTEXITCODE -ne 0) { throw ('Zeitabgleich fehlgeschlagen (Code ' + $LASTEXITCODE + '). Besteht eine Internetverbindung?') }
}
